{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": [
        "C11"
      ],
      "claim": "In rats, a brain/plasma concentration ratio (Kp) of 3.4 at 1 h after intravenous administration demonstrates meaningful brain penetrability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": [
        "C04"
      ],
      "claim": "In rats, a radiolabeled compound showed a brain-to-blood ratio greater than 20:1 at 15 min and remained above 20:1 at 4 h, indicating robust and sustained CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": [
        "C03"
      ],
      "claim": "In control rats, brain interstitium concentrations of CPT-11 and SN-38 were less than 1% of plasma levels by in vivo microdialysis, indicating low CNS penetration for that molecule under intact-BBB conditions.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most retrieved molecules show direct, systemic CNS access through Kp values, brain-to-blood ratios, brain tissue concentrations, CSF detection, or functional CNS effects. One molecule had low unbound brain penetration by microdialysis, but the overall weight of direct in-vivo evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "Molecule 3 has conflicting evidence: positive brain/plasma ratios under brain-tumor or FUS-disrupted conditions versus low brain interstitium/plasma in normal rats; the normal-rat microdialysis record is the most direct intact-BBB measurement.",
    "Several supportive records are qualitative or total brain/plasma ratios rather than unbound brain concentrations, though they still demonstrate systemic CNS exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

